# ---------------------------------------------------------------------------
# Unbehandelte Ausnahmen
# ---------------------------------------------------------------------------
# Die EXE wird mit console=False gebaut, damit ist sys.stderr leer. Tkinter
# schreibt einen Fehler aus einem Knopf-Handler genau dorthin - er verschwand
# also spurlos: kein Protokolleintrag, keine Meldung, nichts im
# Diagnosebericht. Der Knopf tat einfach nichts.
#
# Drei Haken decken die drei Wege ab, auf denen eine Ausnahme das Programm
# verlassen kann:
#   * Tk-Ereignisse (Knoepfe, Bindungen, after-Aufrufe) -> report_callback_exception
#   * der Hauptfaden                                    -> sys.excepthook
#   * die Arbeitsfaeden                                 -> threading.excepthook
_LETZTE_FEHLER: "deque[str]" = deque(maxlen=20)


def _fehler_festhalten(quelle: str, art, wert, spur) -> None:
    """Schreibt eine unbehandelte Ausnahme ins Protokoll und in den Bericht.

    Faengt selbst alles ab: Ein Fehler beim Melden eines Fehlers darf das
    Programm nicht mitreissen, und im Fensterbetrieb gibt es keinen Ort, an
    dem er sichtbar wuerde.
    """
    try:
        spurtext = "".join(traceback.format_exception(art, wert, spur))
        kopf = "%s | %s | %s: %s" % (
            datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            quelle, getattr(art, "__name__", art), wert)
        _LETZTE_FEHLER.append(kopf + "\n" + spurtext.rstrip())
        logger.error("Unbehandelte Ausnahme (%s): %s", quelle, wert,
                     exc_info=(art, wert, spur))
    except Exception:
        pass


def _haken_setzen() -> None:
    """Haengt sys.excepthook und threading.excepthook ein."""
    def _haupt(art, wert, spur):
        _fehler_festhalten("Hauptfaden", art, wert, spur)

    def _faden(args):
        name = getattr(getattr(args, "thread", None), "name", "?")
        _fehler_festhalten("Faden %s" % name,
                           args.exc_type, args.exc_value, args.exc_traceback)

    sys.excepthook = _haupt
    try:
        threading.excepthook = _faden      # ab Python 3.8
    except Exception as exc:
        logger.debug("threading.excepthook nicht setzbar: %s", exc)



def _bundled_resource(*parts: str) -> str:
    """Liefert den Pfad zu einer mitgelieferten Ressource – im Skript wie in der EXE.

    PyInstaller entpackt eingebettete Daten zur Laufzeit nach ``sys._MEIPASS``;
    im Skriptbetrieb liegen sie neben der Quelldatei. Beide Orte werden geprüft,
    sodass Aufrufer keinen Unterschied kennen müssen.

    Returns:
        Vorhandener Pfad oder leerer String.
    """
    roots: list[str] = []
    meipass = getattr(sys, "_MEIPASS", "")
    if meipass:
        roots.append(str(meipass))
    roots.append(os.path.dirname(os.path.abspath(__file__)))
    try:
        roots.append(os.path.dirname(os.path.abspath(sys.argv[0])))
    except Exception:
        pass

    seen: set[str] = set()
    for root in roots:
        key = os.path.normcase(root)
        if not root or key in seen:
            continue
        seen.add(key)
        candidate = os.path.join(root, *parts)
        if os.path.exists(candidate):
            return candidate
    return ""


def _rmtree_force(path: str, ignore_errors: bool = True) -> bool:
    """Löscht einen Baum auch dann, wenn Dateien schreibgeschützt sind.

    UFS2Tool/Dokan-Extraktionen übernehmen das ReadOnly-Attribut aus dem Image.
    ``shutil.rmtree`` scheitert daran unter Windows mit ``[WinError 5]``, und mit
    ``ignore_errors=True`` bleibt der komplette Ordner still liegen – bei einem
    Game-Dump schnell mehrere hundert GB. Deshalb wird das Attribut im
    Fehlerfall zurückgesetzt und der Löschvorgang wiederholt.

    Returns:
        True, wenn der Pfad danach nicht mehr existiert.
    """
    if not path or not os.path.exists(path):
        return True

    def _on_error(func, failed_path, _exc_info):  # type: ignore[no-untyped-def]
        try:
            os.chmod(failed_path, stat.S_IWRITE | stat.S_IREAD)
            func(failed_path)
        except OSError as exc:
            logger.debug("Pfad nicht löschbar (%s): %s", failed_path, exc)
            raise

    try:
        try:
            # onexc ersetzt ab Python 3.12 das veraltete onerror.
            if sys.version_info >= (3, 12):
                shutil.rmtree(path, onexc=lambda f, p, e: _on_error(f, p, e))
            else:
                shutil.rmtree(path, onerror=_on_error)
        except TypeError:
            # shutil.rmtree wurde ersetzt (Monkeypatching in Tests) und kennt
            # den Fehler-Handler nicht – dann ohne Handler löschen.
            shutil.rmtree(path)
    except Exception as exc:
        logger.debug("rmtree fehlgeschlagen (%s): %s", path, exc)
        if not ignore_errors:
            raise
    return not os.path.exists(path)


