# Datei-Handler fuer persistentes Logging (INFO+) in %TEMP%\ps5converter.log
#
# Zwei Dinge, die am 23.08.2026 an einem echten Diagnosebericht auffielen:
#
# 1. **Die Testreihe schrieb mit.** Jeder Lauf aus der Quelle haengte seine
#    Zeilen an dieselbe Datei wie das laufende Programm des Nutzers - gemessen
#    114 Zeilen aus einer einzigen Testdatei. Im Diagnosebericht stand danach
#    Testrauschen statt der Sitzung des Nutzers; eine Meldung erschien
#    siebzehnmal und sah nach einem Programmfehler aus, war aber nur der
#    Rueckstand mehrerer Testlaeufe. ``sys.frozen`` unterscheidet die
#    ausgelieferte EXE sicher von einem Lauf aus der Quelle, und ``unittest``
#    im Modulbestand zeigt den Testlauf an. Beides zusammen, damit ein
#    normaler Start aus der Quelle sein Protokoll behaelt.
# 2. **Die Datei wuchs ungebremst** - 22 MB in gut zwei Wochen. Jetzt rollt
#    sie bei 4 MB um und behaelt drei Vorgaenger.
_IM_TESTLAUF = (not getattr(sys, "frozen", False)) and "unittest" in sys.modules
try:
    import tempfile as _tmpmod
    from logging.handlers import RotatingFileHandler as _RotHandler
    _log_path = os.path.join(_tmpmod.gettempdir(), "ps5converter.log")
    if _IM_TESTLAUF:
        _log_path = os.path.join(_tmpmod.gettempdir(), "ps5converter_test.log")
    _fh = _RotHandler(_log_path, maxBytes=4 * 1024 * 1024, backupCount=3,
                      encoding="utf-8", delay=True)
    _fh.setLevel(logging.INFO)
    _fh.setFormatter(logging.Formatter(
        "%(asctime)s [%(levelname)-8s] %(name)s: %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    ))
    if not _IM_TESTLAUF:
        logger.addHandler(_fh)
    logger.setLevel(logging.INFO)  # Release: INFO+ in Datei, Debug bleibt nur auf Codepfad-Ebene

    # Stuerzt der Interpreter hart ab, greift kein einziger der drei
    # Ausnahmehaken: Ein Speicherzugriffsfehler in einer C-Erweiterung
    # (zlib-ng, zstandard, Pillow, cryptography) beendet den Prozess sofort,
    # und der Nutzer sieht ein Fenster, das einfach verschwindet.
    #
    # ``faulthandler`` schreibt in diesem Fall den Stapel aller Faeden in
    # eine eigene Datei - das Einzige, was danach noch Auskunft gibt.
    # Bewusst NICHT in die Protokolldatei: Der Abzug entsteht ausserhalb der
    # Python-Ebene, mitten in einer halb geschriebenen Protokollzeile.
    if not _IM_TESTLAUF:
        _absturz_pfad = os.path.join(_tmpmod.gettempdir(), "ps5converter_absturz.txt")
        _absturz_datei = io.open(_absturz_pfad, "a", encoding="utf-8")
        faulthandler.enable(file=_absturz_datei)
except OSError:
    pass  # Log-Datei nicht kritisch

# ---------------------------------------------------------------------------
# Win32-API-Helfer fuer korrekte Taskleisten-Integration
# ---------------------------------------------------------------------------
# Hintergrund:
#   overrideredirect(True) entfernt den Windows-Rahmen, loescht aber auch
#   WS_EX_APPWINDOW aus den Extended Window Styles. Ohne dieses Flag zeigt
#   Windows keine Taskleisten-Vorschau und bringt das Fenster beim Klick
#   auf den Taskleisteneintrag nicht in den Vordergrund.
# Loesung:
#   Nach dem Erstellen des Fensters wird WS_EX_APPWINDOW via SetWindowLongW
#   explizit gesetzt. Zusaetzlich wird SetForegroundWindow verwendet, um
#   das Fenster beim Taskleisten-Klick korrekt zu aktivieren.
# ---------------------------------------------------------------------------

if sys.platform == "win32":
    import ctypes  # noqa: F811

    _user32   = ctypes.windll.user32
    _dwmapi   = ctypes.windll.dwmapi

    GWL_EXSTYLE        = -20
    WS_EX_APPWINDOW    = 0x00040000
    WS_EX_TOOLWINDOW   = 0x00000080
    WS_EX_NOACTIVATE   = 0x08000000
    SW_MINIMIZE        = 6
    SW_RESTORE         = 9
    WM_SETICON         = 0x0080
    ICON_SMALL         = 0
    ICON_BIG           = 1
    IMAGE_ICON         = 1
    LR_LOADFROMFILE    = 0x0010
    LR_DEFAULTSIZE     = 0x0040
    GCLP_HICON         = -14
    GCLP_HICONSM       = -34
    SM_CXICON          = 11
    SM_CYICON          = 12
    SM_CXSMICON        = 49
    SM_CYSMICON        = 50

    def _get_hwnd(tk_widget) -> int:
        """Gibt das Win32-HWND fuer ein Tk-Widget zurueck."""
        return _user32.GetParent(tk_widget.winfo_id()) or tk_widget.winfo_id()

    def _apply_appwindow_style(tk_widget) -> None:
        """Setzt WS_EX_APPWINDOW und entfernt WS_EX_TOOLWINDOW.

        Muss nach overrideredirect(True) und nach dem ersten update_idletasks()
        aufgerufen werden, damit Windows das Fenster korrekt in der Taskleiste
        registriert und die DWM-Vorschau aktiviert.
        """
        try:
            hwnd = _get_hwnd(tk_widget)
            ex_style = _user32.GetWindowLongW(hwnd, GWL_EXSTYLE)
            # WS_EX_TOOLWINDOW entfernen (verhindert Taskleisteneintrag)
            ex_style &= ~WS_EX_TOOLWINDOW
            # WS_EX_APPWINDOW setzen (erzwingt Taskleisteneintrag + DWM-Vorschau)
            ex_style |= WS_EX_APPWINDOW
            _user32.SetWindowLongW(hwnd, GWL_EXSTYLE, ex_style)
            # Fenster kurz verstecken und wieder anzeigen damit Windows
            # den neuen Style sofort uebernimmt
            _user32.SetWindowPos(
                hwnd, 0, 0, 0, 0, 0,
                0x0001 | 0x0002 | 0x0004 | 0x0010 | 0x0020  # SWP_NOMOVE|NOSIZE|NOZORDER|NOACTIVATE|FRAMECHANGED
            )
        except Exception as exc:
            logger.debug("Win32 SetWindowPos fehlgeschlagen (nicht-Windows): %s", exc)

    def _apply_win32_window_icon(tk_widget, icon_path: str) -> None:
        """Setzt unter Windows explizit kleine/grosse Fenster-Icons fuer die Taskleiste."""
        try:
            if not icon_path or not os.path.isfile(icon_path):
                return
            try:
                tk_widget.update_idletasks()
            except Exception:
                pass
            hwnd = _get_hwnd(tk_widget)
            big_w = max(1, int(_user32.GetSystemMetrics(SM_CXICON) or 32))
            big_h = max(1, int(_user32.GetSystemMetrics(SM_CYICON) or 32))
            small_w = max(1, int(_user32.GetSystemMetrics(SM_CXSMICON) or 16))
            small_h = max(1, int(_user32.GetSystemMetrics(SM_CYSMICON) or 16))
            load_flags = LR_LOADFROMFILE | LR_DEFAULTSIZE
            big_icon = _user32.LoadImageW(None, icon_path, IMAGE_ICON, big_w, big_h, load_flags)
            small_icon = _user32.LoadImageW(None, icon_path, IMAGE_ICON, small_w, small_h, load_flags)
            if big_icon:
                _user32.SendMessageW(hwnd, WM_SETICON, ICON_BIG, big_icon)
                try:
                    _user32.SetClassLongPtrW(hwnd, GCLP_HICON, big_icon)
                except Exception:
                    pass
            if small_icon:
                _user32.SendMessageW(hwnd, WM_SETICON, ICON_SMALL, small_icon)
                try:
                    _user32.SetClassLongPtrW(hwnd, GCLP_HICONSM, small_icon)
                except Exception:
                    pass
            if big_icon or small_icon:
                setattr(tk_widget, "_win32_icon_handles", (big_icon, small_icon))
        except Exception as exc:
            logger.debug("Win32 Taskleisten-Icon konnte nicht gesetzt werden: %s", exc)

    def _bring_to_front(tk_widget) -> None:
        """Bringt das Fenster in den Vordergrund (umgeht Windows-Fokus-Schutz)."""
        try:
            hwnd = _get_hwnd(tk_widget)
            # AllowSetForegroundWindow + SetForegroundWindow
            _user32.AllowSetForegroundWindow(0xFFFFFFFF)
            _user32.ShowWindow(hwnd, SW_RESTORE)
            _user32.SetForegroundWindow(hwnd)
            _user32.BringWindowToTop(hwnd)
        except Exception as exc:
            logger.debug("Win32 SetForegroundWindow fehlgeschlagen (nicht-Windows): %s", exc)
else:
    def _apply_appwindow_style(tk_widget) -> None:  # type: ignore[misc]
        pass

    def _bring_to_front(tk_widget) -> None:  # type: ignore[misc]
        pass

def parse_sfo(data: bytes) -> dict[str, object]:
    """Parst eine param.sfo-Datei und extrahiert Metadaten.

    Args:
        data: Rohe Bytes der .sfo-Datei.

    Returns:
        Dictionary mit Schl├╝ssel-Wert-Paaren aus der SFO-Datei,
        oder ein leeres Dictionary bei Fehler.
    """
    try:
        if data[:4] != b'\x00PSF':
            return {}

        # Der Kopf traegt VIER Felder: Version, key_offset, data_offset,
        # count. Wer hier header[0..2] nimmt, liest die Version als
        # key_offset und die Datentabellen-Adresse als Anzahl - der Leser
        # scheitert dann an "unpack requires a buffer of 16 bytes" und
        # liefert {}. Genau das war bis v1.8.92 der Fall.
        _version, key_ptr, data_ptr, count = struct.unpack('<IIII', data[4:20])

        entries = []
        for i in range(count):
            entry = struct.unpack('<HHIII', data[20 + i * 16: 20 + (i + 1) * 16])
            entries.append(entry)

        results: dict[str, object] = {}
        for key_off, data_fmt, data_len, _data_max, data_off in entries:
            k_start = key_ptr + key_off
            k_end = data.find(b'\x00', k_start)
            key = data[k_start:k_end].decode('utf-8')

            v_start = data_ptr + data_off
            if data_fmt == 0x0204:   # UTF-8-String
                v_end = data.find(b'\x00', v_start)
                value: object = data[v_start:v_end].decode('utf-8')
            elif data_fmt == 0x0004:  # 32-Bit-Integer
                value = struct.unpack('<I', data[v_start:v_start + 4])[0]
            else:
                value = data[v_start:v_start + data_len]

            results[key] = value

        return results

    except struct.error as exc:
        logger.warning("SFO-Parsing fehlgeschlagen (Strukturfehler): %s", exc)
        return {}
    except UnicodeDecodeError as exc:
        logger.warning("SFO-Parsing fehlgeschlagen (Dekodierungsfehler): %s", exc)
        return {}
    except Exception as exc:  # noqa: BLE001
        logger.warning("SFO-Parsing fehlgeschlagen (Unerwarteter Fehler): %s", exc)
        return {}

